\node[right, font=\fontsize{17.5}{21}\selectfont] at (D) {$D$};
\node[above, font=\fontsize{17.5}{21}\selectfont] at (B) {$B$};
\node[below, font=\fontsize{17.5}{21}\selectfont] at (C) {$C$};
